ruleToc.chapterList:
@css:.detail_lst>ul>li:eq(0)>a:eq(0)@js:
var urls=result.match(/href="([^"]*?)(\d+)"/);
var url=urls[1].replace(/&amp;/,"&");
var count=+urls[2]+1;
list=[];
for(var i=1;i<count;++i){
list.push({url:url+i,text:"第"+i+"话"});
}
;list

